import {renderOnline} from './lobby-layout.mjs';
import {profileView,adminView} from './club-views.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const roles=['星语法师','齿轮工匠','星际守护','森林游侠'];
export async function clubApi(path,body){const res=await fetch('/api/'+path,{method:body?'POST':'GET',credentials:'same-origin',cache:'no-store',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});if(res.status===401){location.reload();throw Error('请重新进入游戏')}const data=await res.json();if(!res.ok)throw Error(data.error||'连接失败');return data}
export class ClubUI{
 constructor({onReady,onBank,onBlocked}){Object.assign(this,{onReady,onBank,onBlocked});this.started=false;this.panel=null;document.querySelector('#app').textContent='正在连接玩家中心…';this.button=document.createElement('button');this.button.className='club-entry';this.button.textContent='玩家 / 管理';this.button.onclick=()=>this.open();document.querySelector('header').append(this.button);this.refresh()}
 async refresh(){try{const data=await clubApi('session');this.data=data;window.clubPlayer=data.player;renderOnline(data);this.onBank(data.player.bank+data.player.tableBank);const ok=data.player.name&&data.player.status==='allowed';if(ok&&!this.started){this.started=true;this.panel?.close();this.onReady()}else if(!ok){if(this.started){this.onBlocked();this.started=false}if(!this.panel?.open)this.open()}if(this.panel?.open&&this.waiting&&!['INPUT','SELECT'].includes(document.activeElement?.tagName))this.showProfile();}catch(e){if(!this.started)document.querySelector('#app').textContent=e.message}finally{this.timer=setTimeout(()=>this.refresh(),15000)}}
 open(){if(!this.panel){this.panel=document.createElement('dialog');this.panel.className='club-panel';this.panel.id='clubPanel';document.body.append(this.panel);this.panel.addEventListener('cancel',e=>{if(!this.started)e.preventDefault()})}if(!this.panel.open)this.panel.showModal();this.showProfile()}
 shell(title,content){this.panel.innerHTML=`<div class="club-title"><h2>${title}</h2>${this.started?'<button class="club-close" data-close aria-label="关闭">×</button>':''}</div><div class="club-content">${content}</div><p class="club-error" role="alert"></p>`;this.panel.querySelector('[data-close]')?.addEventListener('click',()=>{this.waiting=false;clearTimeout(this.adminTimer);this.panel.close()})}
 error(e){this.panel.querySelector('.club-error').textContent=e.message}
 showProfile(){clearTimeout(this.adminTimer);const p=this.data?.player;if(!p)return;this.waiting=!!p.name&&p.status!=='allowed';this.panel.dataset.view='profile';this.shell(p.status!=='allowed'&&p.name?'入场申请':p.name?'玩家中心':'欢迎入座',profileView(this.data));const formNode=this.panel.querySelector('[data-profile]');if(formNode)formNode.onsubmit=async e=>{e.preventDefault();try{const form=new FormData(e.target);await clubApi('profile',{name:form.get('name'),...(form.has('role')?{role:+form.get('role')}:{})});await this.refreshOnce();if(!this.started||this.panel.open)this.showProfile()}catch(e){this.error(e)}};this.panel.querySelector('[data-resume]')?.addEventListener('click',()=>{location.href='/?room='+p.activeRoom});this.panel.querySelector('[data-admin]').onclick=()=>this.data.admin?this.showAdmin():this.login()}
 async refreshOnce(){this.data=await clubApi('session');window.clubPlayer=this.data.player;renderOnline(this.data);if(this.data.player.status==='allowed'&&this.data.player.name&&!this.started){this.started=true;this.waiting=false;this.panel?.close();this.onReady()}this.onBank(this.data.player.bank+this.data.player.tableBank)}
 login(){this.waiting=false;this.panel.dataset.view='login';this.shell('管理员登录','<form data-login><label>管理员密码<input type="password" name="password" autocomplete="current-password" required maxlength="128"></label><button class="club-primary">登录</button></form><button class="club-link" data-back>返回玩家中心</button>');this.panel.querySelector('[data-back]').onclick=()=>this.showProfile();this.panel.querySelector('form').onsubmit=async e=>{e.preventDefault();try{await clubApi('admin/login',{password:new FormData(e.target).get('password')});await this.refreshOnce();this.showAdmin()}catch(e){this.error(e)}}}
 async showAdmin(){this.waiting=false;clearTimeout(this.adminTimer);try{const data=await clubApi('admin');if(!this.panel.open)return;const online=data.players.filter(p=>p.online).length;this.panel.dataset.view='admin';this.shell('玩家管理',adminView(data));this.panel.querySelector('[data-back]').onclick=()=>this.showProfile();this.panel.querySelector('[data-logout]').onclick=async()=>{await clubApi('admin/logout',{});await this.refreshOnce();this.showProfile()};this.panel.querySelectorAll('[data-permission]').forEach(b=>b.onclick=()=>this.manage({kind:'permission',id:b.dataset.permission,status:b.dataset.status},b));this.panel.querySelectorAll('[data-grant]').forEach(f=>f.onsubmit=e=>{e.preventDefault();this.manage({kind:'grant',id:f.dataset.grant,amount:+f.querySelector('input').value},f.querySelector('button'))});this.panel.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{if(confirm('删除此玩家的昵称、形象、权限及筹码？若正在牌局中，该牌局也会关闭，其他玩家的筹码会退回。此设备重新登记后需要管理员允许，且不会再次赠送筹码。'))this.manage({kind:'deletePlayer',id:b.dataset.delete},b)});this.panel.querySelectorAll('[data-close-room]').forEach(b=>b.onclick=()=>{if(confirm('关闭此牌局？所有玩家的可用筹码与未结算下注将退回。'))this.manage({kind:'closeRoom',id:b.dataset.closeRoom},b)});this.adminTimer=setTimeout(()=>this.pollAdmin(),15000)}catch(e){this.error(e)}}
 pollAdmin(){if(!this.panel.open)return;if(['INPUT','SELECT'].includes(document.activeElement?.tagName)&&this.panel.contains(document.activeElement)){this.adminTimer=setTimeout(()=>this.pollAdmin(),5000);return}this.showAdmin()}
 async manage(data,b){b.disabled=true;try{await clubApi('admin',{...data,requestId:crypto.randomUUID().replaceAll('-','')});await this.refreshOnce();await this.showAdmin()}catch(e){this.error(e);b.disabled=false}}
}
